<script lang="ts">
 import {onMount} from 'svelte';
 import {Api} from './api';
 import type {Template} from './types';
 let {onpreview,onlogin,onsignup,oncontribute,signedIn}:{onpreview:(t:Template)=>void;onlogin:()=>void;onsignup:()=>void;oncontribute:()=>void;signedIn:boolean}=$props();
 let items=$state<Template[]>([]);let q=$state('');let error=$state('');let loading=$state(false);let generation=0;let locale=$state('en-US');
 async function load(){const current=++generation;loading=true;error='';try{const r=await new Api().publicTemplates(q,locale);if(current===generation)items=r.items;}catch(e){if(current===generation)error=e instanceof Error?e.message:'Could not load public templates.';}finally{if(current===generation)loading=false;}}
 onMount(()=>{void load();return()=>{generation++;};});
</script>
<main class="library-page public-page"><div class="page-heading"><div><span class="eyebrow">GOOD STARTS, SHARED</span><h1>Public memories<span class="heading-dot">.</span></h1><p>Browse, search, and preview memories without signing in.</p></div><div class="public-actions">{#if !signedIn}<button class="secondary" onclick={onlogin}>Sign in with email →</button><button class="secondary" onclick={onsignup}>Create account</button>{/if}<button class="primary" onclick={oncontribute}>{signedIn?'Contribute a template +':'Sign in to contribute →'}</button></div></div>
 <p class="public-access">Anyone can create a free personal account. Contribution requests require sign-in and become public after approval.</p>
 <form class="public-search" onsubmit={(e)=>{e.preventDefault();void load();}}><label class="visually-hidden" for="public-query">Search public templates</label><input id="public-query" type="search" maxlength="200" bind:value={q} placeholder="Search public templates"/><select aria-label="Public template language" bind:value={locale} onchange={()=>void load()}><option value="en-US">English</option><option value="all">All languages</option><option value="ko-KR">Korean</option></select><button class="secondary" disabled={loading}>Search</button></form>
 {#if error}<div class="alert" role="alert">{error}<button class="text-button" onclick={load}>Try again</button></div>{/if}{#if loading}<p role="status">Loading public memories…</p>{/if}
 <div class="public-grid">{#each items as t (t.id)}<article class="public-card"><div><span class="pill">Public template · {t.form.family==='deck'?'Slides':t.form.family==='sheet'?'Spreadsheet':'Document'}</span><span class="card-number">{t.form.locale}</span></div><h2>{t.title}</h2><p>{t.summary}</p><ol>{#each t.sections.slice(0,3) as section}<li>{section}</li>{/each}</ol><footer><small>{t.author} · {t.license}</small><button class="text-button" disabled={loading} onclick={()=>onpreview(t)} aria-label={t.title+' public preview'}>Preview ↗</button></footer></article>{:else}{#if !loading&&!error}<p class="empty-public">No results. Try another search.</p>{/if}{/each}</div><p class="public-footnote">Only template structures are public. Copies stay in your private space with their original author and version.</p>
</main>
<style>
 .public-actions{display:flex;flex-wrap:wrap;gap:8px}.public-actions button{font-size:12px}.public-access{font-size:13px;color:#65705e;line-height:1.8;margin:-8px 0 24px}
 .public-search{display:flex;flex-wrap:wrap;gap:12px;margin-bottom:28px;max-width:600px}.public-search input{flex:1 1 180px;min-width:0}.public-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.public-card{border:1px solid #dee2d5;border-radius:15px;background:white;padding:24px;display:flex;flex-direction:column;min-width:0}.public-card>div{display:flex;justify-content:space-between;gap:10px}.public-card h2{font-size:21px;line-height:1.5;margin:22px 0 8px;overflow-wrap:anywhere}.public-card p{font-size:13px;color:#707866;line-height:1.8}.public-card ol{font-size:12px;line-height:2.3;color:#7a826f;padding-left:18px;margin-bottom:25px}.public-card footer{border-top:1px solid #edefe7;padding-top:14px;margin-top:auto;display:grid;gap:12px}.public-card small{font-size:10px;color:#78816c}.card-number{font-size:10px;color:#89917e}.public-card button{text-align:left}.public-footnote{font-size:12px;color:#7d856f;margin-top:28px;line-height:1.8}.empty-public{padding:40px;color:#7d856f}@media(max-width:1200px){.public-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:700px){.public-grid{grid-template-columns:1fr}.public-card{padding:20px}}
</style>
